mkdir -p /tmp/work && cat > /tmp/work/recon.py <<'EOF'
import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
from decimal import Decimal
B="http://localhost:8080"
tok=None
log=[]
def new_token():
    global tok
    r=urllib.request.Request(B+"/token",method="POST")
    tok=json.load(urllib.request.urlopen(r))["token"]
def get(path):
    global tok
    for attempt in range(200):
        if tok is None: new_token()
        req=urllib.request.Request(B+path,headers={"Authorization":"Bearer "+tok})
        try:
            with urllib.request.urlopen(req) as r:
                return json.load(r)
        except urllib.error.HTTPError as e:
            body=e.read().decode()
            hdr=dict(e.headers)
            if e.code==404: return {"__404__":True}
            log.append((path,e.code,body[:200],hdr.get("Retry-After")))
            if e.code==401 or e.code==403:
                new_token(); continue
            if e.code==429:
                ra=hdr.get("Retry-After")
                try: w=float(ra)
                except: 
                    try: w=float(json.loads(body).get("retry_after",1))
                    except: w=1
                time.sleep(w+0.05); continue
            time.sleep(0.5)
        except Exception as e:
            log.append((path,"exc",repr(e),None)); time.sleep(0.5)
    raise RuntimeError(path)
orders=[]; page=1; path="/orders?page=1"
while path:
    d=get(path)
    if "items" not in d:
        log.append((path,"badshape",str(d)[:200],None)); time.sleep(0.5); continue
    orders.append((path,d["items"]))
    path=d["next"]
json.dump(orders,open("/tmp/work/orders_raw.json","w"))
json.dump(log,open("/tmp/work/log.json","w"))
print(len(orders),"pages", sum(len(i) for _,i in orders),"items")
print(len(log),"errors; sample",log[:8])
EOF
python3 -I /tmp/work/recon.py

